SELECT * FROM byai.byai_group_chat_forward_request
  WHERE enterprise_id=#{enterpriseId}
  AND request_id=#{requestId}

SELECT * FROM byai.byai_group_chat_forward_request
  WHERE enterprise_id=#{enterpriseId}
  AND actor_user_id=#{actorUserId}
  AND client_request_id=#{clientRequestId}

SELECT * FROM byai.byai_group_chat_forward_target
  WHERE enterprise_id=#{enterpriseId}
  AND target_id=#{targetId}

SELECT * FROM byai.byai_group_chat_forward_target
  WHERE enterprise_id=#{enterpriseId}
  AND request_id=#{requestId}
  ORDER BY target_session_id

SELECT * FROM byai.byai_group_chat_forward_item
  WHERE enterprise_id=#{enterpriseId}
  AND target_id=#{targetId}
  ORDER BY ordinal

mapper.update:
UPDATE byai.byai_group_chat_forward_request
  SET source_manifest_json=#{sourceManifestJson}, sources_frozen=TRUE, fencing_version=fencing_version+1, lease_owner=NULL, lease_until=NULL, update_time=CURRENT_TIMESTAMP
WHERE enterprise_id=#{enterpriseId}
  AND request_id=#{requestId}
  AND state='RUNNING'
  AND sources_frozen=FALSE
  AND lease_owner=#{owner}
  AND fencing_version=#{version}
  AND lease_until > clock_timestamp()

UPDATE byai.byai_group_chat_forward_target
  SET checkpoint_json=#{checkpointJson}, state=#{state}, fencing_version=fencing_version+1, update_time=CURRENT_TIMESTAMP
WHERE enterprise_id=#{enterpriseId}
  AND target_id=#{targetId}
  AND lease_owner=#{owner}
  AND fencing_version=#{version}
  AND lease_until > clock_timestamp()
  AND ((state='COPYING'
  AND #{state} IN ('COPYING','READY')) OR (state='READY'
  AND #{state}='READY'))

UPDATE byai.byai_group_chat_forward_target
  SET state='SUCCEEDED', message_ids_json=#{messageIdsJson}, pending_delivery=TRUE, error_code=NULL, retryable=FALSE, lease_owner=NULL, lease_until=NULL, fencing_version=fencing_version+1, update_time=CURRENT_TIMESTAMP
WHERE enterprise_id=#{enterpriseId}
  AND target_id=#{targetId}
  AND state='READY'
  AND lease_owner=#{owner}
  AND fencing_version=#{version}
  AND lease_until > clock_timestamp()

UPDATE byai.byai_group_chat_forward_target
  SET state='FAILED', error_code=#{errorCode}, retryable=#{retryable}, lease_owner=NULL, lease_until=NULL, fencing_version=fencing_version+1, update_time=CURRENT_TIMESTAMP
WHERE enterprise_id=#{enterpriseId}
  AND target_id=#{targetId}
  AND state IN ('COPYING','READY')
  AND lease_owner=#{owner}
  AND fencing_version=#{version}
  AND lease_until > clock_timestamp()

UPDATE byai.byai_group_chat_forward_request
  SET state=#{state}, update_time=CURRENT_TIMESTAMP
  WHERE enterprise_id=#{enterpriseId}
  AND request_id=#{requestId}
  AND state <> 'SUCCEEDED'

UPDATE byai.byai_group_chat_forward_target
  SET pending_delivery=FALSE, update_time=CURRENT_TIMESTAMP
  WHERE enterprise_id=#{enterpriseId}
  AND target_id=#{targetId}
  AND state='SUCCEEDED'
  AND pending_delivery=TRUE

mapper.select:
SELECT * FROM byai.byai_group_chat_forward_target
  WHERE enterprise_id=#{enterpriseId}
  AND state='SUCCEEDED'
  AND pending_delivery=TRUE
  ORDER BY target_id
  LIMIT #{limit}

SELECT * FROM byai.byai_group_chat_forward_target
  WHERE enterprise_id=#{enterpriseId}
  AND state IN ('PENDING','COPYING','READY')
  AND (lease_until IS NULL OR lease_until <= clock_timestamp())
  ORDER BY target_id
  LIMIT #{limit}

mapper.update:
UPDATE byai.byai_group_chat_forward_item
  SET bound_message_id=#{messageId}, attachments_json=#{attachmentsJson}
  WHERE enterprise_id=#{enterpriseId}
  AND target_id=#{targetId}
  AND item_id=#{itemId}
  AND bound_message_id IS NULL
  AND EXISTS (SELECT 1 FROM byai.byai_group_chat_forward_target t WHERE t.enterprise_id=#{enterpriseId}
  AND t.target_id=#{targetId}
  AND t.state='READY'
  AND t.lease_owner=#{owner}
  AND t.fencing_version=#{version}
  AND t.lease_until > clock_timestamp())

UPDATE byai.byai_group_chat_forward_target
SET lease_until=GREATEST(lease_until, clock_timestamp() + (CAST(#{leaseMillis} AS BIGINT) * INTERVAL '0.001' SECOND)), update_time=CURRENT_TIMESTAMP
WHERE enterprise_id=#{lease.actor.enterpriseId} AND request_id=#{lease.requestId} AND target_id=#{lease.targetId}
AND target_session_id=#{lease.targetSessionId} AND lease_owner=#{lease.owner} AND fencing_version=#{lease.fencingVersion}
AND state IN ('COPYING','READY') AND lease_until > clock_timestamp() AND #{leaseMillis} > 0
AND EXISTS (SELECT 1 FROM byai.byai_group_chat_forward_request r
  WHERE r.enterprise_id=#{lease.actor.enterpriseId} AND r.request_id=#{lease.requestId}
  AND r.actor_user_id=#{lease.actor.userId} AND r.source_session_id=#{lease.sourceSessionId} AND r.state='RUNNING')
